function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];
  let userList = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (users) {
        userList = users;
        const userSelect = container.querySelector("#filter-user");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error("ユーザー一覧の取得に失敗しました:", error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    const noResults = container.querySelector("#no-results");

    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      updatePagination(0);
      return;
    }

    noResults.classList.add("hidden");

    // ページネーション用のデータスライス
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(row => {
      const userName = getUserName(row.ユーザーID);
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultBadge = getResultBadge(row.処理結果);

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td>${resultBadge}</td>
          <td>${row.処理時間 || ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    updatePagination(rows.length);
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = userList.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : userId || '';
  }

  // 処理結果のバッジを生成
  function getResultBadge(result) {
    if (!result) return '';

    let color = '';
    switch (result) {
      case '成功':
        color = 'background: #22c55e; color: white;';
        break;
      case '失敗':
        color = 'background: #ef4444; color: white;';
        break;
      case 'エラー':
        color = 'background: #f59e0b; color: white;';
        break;
      default:
        color = 'background: var(--bg-main); color: var(--text);';
    }

    return `<span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; ${color}">${result}</span>`;
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const prevBtn = container.querySelector("#btn-prev");
    const nextBtn = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${totalPages || 1}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;

    if (totalPages <= 1) {
      container.querySelector("#pagination").style.display = "none";
    } else {
      container.querySelector("#pagination").style.display = "flex";
    }
  }

  // フィルタリング処理
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const userId = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value.toLowerCase();
    const result = container.querySelector("#filter-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert("不正なIPアドレス形式です。正しい形式で入力してください。");
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const rowDate = new Date(row.操作日時);
        if (startDate && rowDate < new Date(startDate)) return false;
        if (endDate && rowDate > new Date(endDate + 'T23:59:59')) return false;
      }

      // ユーザーフィルター
      if (userId && row.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && row.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && !row.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && !row.IPアドレス?.toLowerCase().includes(ipAddress)) return false;

      // 処理結果フィルター
      if (result && row.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  // IPアドレス形式チェック
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip) || ip === ''; // 空文字は許可
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector("#filter-start-date").value = '';
    container.querySelector("#filter-end-date").value = '';
    container.querySelector("#filter-user").value = '';
    container.querySelector("#filter-operation-type").value = '';
    container.querySelector("#filter-screen-name").value = '';
    container.querySelector("#filter-ip-address").value = '';
    container.querySelector("#filter-result").value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderRows(filteredData);
  }

  // CSV出力
  async function exportCSV() {
    try {
      const data = filteredData.length > 0 ? filteredData : allHistoryData;

      if (data.length > 100000) {
        alert("データ量が多すぎます。検索条件を絞り込んでから出力してください。");
        return;
      }

      const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

      const csvContent = [
        headers.join(','),
        ...data.map(row => [
          `"${row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : ''}"`,
          `"${getUserName(row.ユーザーID)}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.操作対象テーブル || ''}"`,
          `"${row.操作対象ID || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${row.IPアドレス || ''}"`,
          `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${row.処理時間 || ''}"`
        ].join(','))
      ].join('\n');

      const bom = '\uFEFF';
      const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `システム操作履歴_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
      URL.revokeObjectURL(link.href);
    } catch (error) {
      alert("CSV出力中にエラーが発生しました。");
      console.error("CSV export error:", error);
    }
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector("#detail-datetime").textContent = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';
    container.querySelector("#detail-user").textContent = getUserName(history.ユーザーID);
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-target").textContent = `${history.操作対象テーブル || ''} ${history.操作対象ID || ''}`.trim();
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-useragent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-content-text").textContent = history.操作内容 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';

    container.querySelector("#detail-modal").classList.remove("hidden");
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const historyData = await window.aivicApi.list(13); // システム操作履歴テーブル
      if (historyData) {
        allHistoryData = historyData.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredData = [...allHistoryData];
        renderRows(filteredData);
      } else {
        allHistoryData = tables[13]?.records || [];
        filteredData = [...allHistoryData];
        renderRows(filteredData);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      allHistoryData = tables[13]?.records || [];
      filteredData = [...allHistoryData];
      renderRows(filteredData);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // モーダル関連
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });

  // 初期化
  loadUsers();
  loadData();
}
